/// Drops separators with nothing beside them: leading, trailing, and every one
/// after the first in a run. A divider earns its line by dividing two things,
/// and which items a poll leaves out is not knowable where they are written —
/// so guarding each separator by hand would mean repeating the conditions of
/// every item around it.
func tidy(_ nodes: [MenuNode]) -> [MenuNode] {
    var out: [MenuNode] = []
    for node in nodes {
        if case .separator = node {
            if out.isEmpty { continue }
            if case .separator = out[out.count - 1] { continue }
            out.append(node)
            continue
        }
        // A row whose header: holds is a label: its submenu or action is dropped.
        if case .submenu(let title, _, let look) = node, look.header {
            out.append(.item(title, nil, look: look))
            continue
        }
        if case .item(let title, _?, let look) = node, look.header {
            out.append(.item(title, nil, look: look))
            continue
        }
        if case .submenu(let title, let items, let look) = node {
            // Every item guarded away leaves a label, not an arrow into nothing.
            let kept = tidy(items)
            out.append(kept.isEmpty ? .item(title, nil, look: look) : .submenu(title, kept, look: look))
            continue
        }
        out.append(node)
    }
    if let last = out.last, case .separator = last { out.removeLast() }
    return out
}

enum Draw {
    /// Everything but enabling, which needs to know whether the item acts.
    static func look(_ look: Look, on item: NSMenuItem) {
        Draw.icon(look.icon, on: item)
        item.attributedTitle = look.title(item.title)
        item.indentationLevel = Int(min(max(look.indent, 0), 15))
        if !look.subtitle.isEmpty, #available(macOS 14.0, *) { item.subtitle = look.subtitle }
        if let key = look.key {
            item.keyEquivalent = key.key
            item.keyEquivalentModifierMask = key.modifiers
        }
    }

    /// An item that does nothing is shown disabled unless enabled: says
    /// otherwise; one that acts is shown enabled unless enabled: says otherwise.
    static func enable(_ item: NSMenuItem, acts: Bool, look: Look) {
        item.isEnabled = look.enabled ?? acts
